mapper.update:
UPDATE chat_session
SET connection_id = #{connectionId},
    terminal_session_id = #{terminalSessionId},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{sessionId}
  AND agent_id = #{agentId}
  AND user_id = #{userId}

UPDATE chat_session
SET message_count = message_count + 1
WHERE id = #{sessionId}

mapper.select:
SELECT id, agent_id, user_id, connection_id, terminal_session_id, title, message_count, created_at, updated_at
FROM chat_session
WHERE user_id = #{userId}
AND agent_id = #{agentId}
ORDER BY updated_at DESC
LIMIT #{limit}

SELECT id, agent_id, user_id, connection_id, terminal_session_id, title, message_count, created_at, updated_at
FROM chat_session
WHERE id = #{sessionId}
  AND agent_id = #{agentId}
  AND user_id = #{userId}
LIMIT 1
